Object.entries(inboxUiTranslations).forEach(([language, values]) => {
  translations[language] = { ...translations[language], ...values };
});

const fallbackKeysByLanguage = {};

// Keep the UI usable while recording which keys still need localization.
SUPPORTED_LANGUAGES.forEach(({ code }) => {
  if (code === 'en') return;
  fallbackKeysByLanguage[code] = new Set();
  Object.keys(translations.en).forEach((key) => {
    if (!translations[code][key]) {
      fallbackKeysByLanguage[code].add(key);
      translations[code][key] = translations.en[key];
    }
  });
});

const languageByCode = (code) => SUPPORTED_LANGUAGES.find((item) => item.code === code) || SUPPORTED_LANGUAGES[0];

const interpolate = (value, params) => value.replace(/\{(\w+)\}/g, (_, key) => params[key] ?? `{${key}}`);

export const getLocale = (language) => languageByCode(language).locale;
export const hasTranslation = (language, key) => language === 'en' || Boolean(translations[language]?.[key] && !fallbackKeysByLanguage[language]?.has(key));

export function useI18n() {
  const language = useAppStore((state) => state.userPreferences.language || 'en');
  const updatePreferences = useAppStore((state) => state.updatePreferences);
  const dictionary = translations[language] || translations.en;
  const t = useCallback(
    (key, params = {}) => interpolate(dictionary[key] || translations.en[key] || key, params),
    [dictionary]
  );
  const setLanguage = (nextLanguage) => updatePreferences({ language: languageByCode(nextLanguage).code });
  const formatNumber = (value, options) => new Intl.NumberFormat(getLocale(language), options).format(value);
  const formatCurrency = (value, currency = 'USD') => new Intl.NumberFormat(getLocale(language), { style: 'currency', currency }).format(value);
  const formatDate = (value, options) => new Intl.DateTimeFormat(getLocale(language), options).format(new Date(value));

  return { language, locale: getLocale(language), languages: SUPPORTED_LANGUAGES, t, setLanguage, formatNumber, formatCurrency, formatDate, hasTranslation: (key) => hasTranslation(language, key) };
}
